local M = class("CastingSwordShareModel", LikeOO.OODataBase)

function M:onCreate()
    M.super.onCreate(self)
    self.m_version = self.m_params.version
    self.m_activityData = self.m_params.actives[1]
    self:setAllTask(self.m_params.share_quests)     -- self.m_allTaskData
    self:getData()
end

function M:setAllTask(share_quests)
    local tempData = {}
    local sword_questData = ConfigManager:getCfgByName("sword_quest")
    local versionRankAwardData = sword_questData[self.m_version] or {}
    for id, taskItemData in pairs(versionRankAwardData) do
        if taskItemData.sort == 2 then
            tempData[taskItemData.type] = {
                xlsxData = taskItemData,
                serverData = share_quests[tostring(id)] or {},
                id = id,
            }
        end
    end
    self.m_allTaskData = tempData
end

-- 完成任务修改
function M:amendTaskData(id)
    for _, itemData in pairs(self.m_allTaskData) do
        if itemData.id == id then
            itemData.serverData.status = 2
            break
        end
    end
end

-- 开服红包活动是否开启中（openId = 178)
function M:isOpenRedBagActivity()
    local isExistActivesRecharge = UserDataManager:getActivesRechargeByOpenId(178)
    local isExistActives = UserDataManager:getActivesByOpenId(178)
    if isExistActivesRecharge or isExistActives then
        return true
    end
    return false
end

return M